import urllib.request, urllib.error, json, time, datetime, email.utils
BASE='http://localhost:8080'
token=None
stats={}
def request(path,auth=True):
 global token
 while True:
  if auth and token is None:
   token=[REDACTED_SECRET]'/token',False)['token']
  req=urllib.request.Request(BASE+path,method='GET' if auth else 'POST',headers={'Authorization':'Bearer '+token} if auth else {})
  try:
   with urllib.request.urlopen(req,timeout=30) as r: return json.load(r)
  except urllib.error.HTTPError as e:
   body=e.read().decode()
   stats[str(e.code)]=stats.get(str(e.code),0)+1
   if e.code==401 and auth:
    token=None
    continue
   delay=e.headers.get('Retry-After')
   if delay:
    try: delay=float(delay)
    except ValueError: delay=max(0,(email.utils.parsedate_to_datetime(delay)-datetime.datetime.now(datetime.timezone.utc)).total_seconds())
   else: delay=1
   print('Retry',path,e.code,body,'wait',delay,flush=True)
   time.sleep(delay)
  except (urllib.error.URLError,TimeoutError,ConnectionError) as e:
   print('Retry',path,str(e),flush=True);time.sleep(1)
seen={};duplicates=0;orders=[];pages=[];path='/orders?page=1'
while path:
 page=request(path)
 pages.append(page['page'])
 for order in page['items']:
  oid=order['id']
  if oid in seen:
   assert seen[oid]==order,('conflicting duplicate',oid)
   duplicates+=1
  else:
   seen[oid]=order;orders.append(order)
 path=page['next']
 print('Page',page['page'],'of',page['total_pages'],'unique',len(seen),flush=True)
assert pages==list(range(1,page['total_pages']+1))
start=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc)
end=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
qualifying=[o for o in orders if o['status']=='shipped' and start<=datetime.datetime.fromisoformat(o['placed_at']).astimezone(datetime.timezone.utc)<end]
customers={}
for cid in sorted(set(o['customer_id'] for o in qualifying)):
 customers[cid]=request('/customers/'+str(cid))
 print('Customer',cid,flush=True)
regions=dict.fromkeys(['north','south','east','west'],0)
for o in qualifying:
 c=customers[o['customer_id']]
 assert isinstance(c['discount_pct'],int) and 0<=c['discount_pct']<=100
 assert o['amount_cents']>=0
 discounted=(o['amount_cents']*(100-c['discount_pct'])+50)//100
 regions[c['region']]+=discounted
result=dict(total_cents=sum(regions.values()),order_count=len(qualifying),duplicates_skipped=duplicates,by_region=regions)
with open('/tmp/reconciliation-audit.json','w') as f:json.dump(dict(orders=orders,customers=customers,result=result,stats=stats),f)
with open('/workspace/result.json','w') as f:json.dump(result,f,indent=2);f.write('\\n')
print('RESULT',json.dumps(result),'RETRIES',stats,flush=True)
